#!/usr/bin/env python3
# patch-158-G7: equalize parts + work order header heights
"""
Parts & products and Work order details headers in each asset card
were rendering at slightly different heights. Two causes:

  1. .ma-asset-parts-head had asymmetric vertical padding
     (10px top, 8px bottom). Made symmetric: 10px top + bottom.
  2. No explicit min-height meant minor differences in glyph
     rendering between the two summaries could shift things by
     a pixel. Locked to 40px min-height.

Single-file CSS-only view patch.
"""
